/**
 * Draws the live movement guide (rehab/biofeedback.ts) over the camera frame, in the frame's own pixels: the canvas is
 * mirrored by CSS together with the video. Affected side: where the points were at rest (thin), where they are now
 * (solid, coloured by the verdict) and the goal (dashed) with an arrow; healthy side: its comfortable ceiling (faint).
 */
import type { Vec2 } from '../../core';
import type { CoachState, GuideLines, GuideSide } from '../../rehab/biofeedback';
import type { StretchMark } from '../../rehab/stretchGuide';

/** Canvas colours (fixed: drawn over video, so they do not follow the page theme). */
export const GUIDE_COLOR: Record<CoachState | 'goal' | 'rest' | 'ceiling', string> = {
  rest: 'rgba(255,255,255,0.75)',
  move: 'rgba(255,200,87,0.98)',
  good: 'rgba(87,214,141,0.98)',
  tooStrong: 'rgba(255,128,112,0.98)',
  unbalanced: 'rgba(255,170,60,0.98)',
  synk: 'rgba(255,128,112,0.98)',
  goal: 'rgba(255,200,87,0.98)',
  ceiling: 'rgba(255,255,255,0.55)',
};

const centroid = (p: readonly Vec2[]): Vec2 => ({
  x: p.reduce((a, q) => a + q.x, 0) / p.length,
  y: p.reduce((a, q) => a + q.y, 0) / p.length,
});

function path(ctx: CanvasRenderingContext2D, pts: readonly Vec2[], line: boolean, r: number): void {
  if (line) {
    ctx.beginPath();
    pts.forEach((p, k) => (k ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)));
    ctx.stroke();
  } else {
    for (const p of pts) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
      ctx.stroke();
    }
  }
}

function dots(ctx: CanvasRenderingContext2D, pts: readonly Vec2[], r: number): void {
  for (const p of pts) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fill();
  }
}

function arrow(ctx: CanvasRenderingContext2D, from: Vec2, to: Vec2, head: number): void {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const len = Math.hypot(dx, dy);
  if (len < head * 1.2) return;
  const ux = dx / len;
  const uy = dy / len;
  const tip = { x: to.x - ux * head * 0.3, y: to.y - uy * head * 0.3 };
  ctx.beginPath();
  ctx.moveTo(from.x, from.y);
  ctx.lineTo(tip.x, tip.y);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(tip.x, tip.y);
  ctx.lineTo(tip.x - ux * head - uy * head * 0.6, tip.y - uy * head + ux * head * 0.6);
  ctx.lineTo(tip.x - ux * head + uy * head * 0.6, tip.y - uy * head - ux * head * 0.6);
  ctx.closePath();
  ctx.fill();
}

/** Draws one frame's guide; `w` is the frame width (line widths scale with it). */
export function drawGuide(ctx: CanvasRenderingContext2D, g: GuideLines, state: CoachState, w: number): void {
  const lw = Math.max(2, w / 300);
  const r = Math.max(4, w / 110);
  const dash = [lw * 3, lw * 2.4];
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // Healthy side: the comfortable ceiling only, faint, so the eye stays on the affected side.
  ctx.setLineDash(dash);
  ctx.lineWidth = lw;
  ctx.strokeStyle = GUIDE_COLOR.ceiling;
  path(ctx, g.healthy.goal, g.line, r);
  ctx.setLineDash([]);
  ctx.fillStyle = GUIDE_COLOR.ceiling;
  dots(ctx, g.healthy.now, r * 0.45);

  drawAffected(ctx, g.affected, g.line, state, lw, r, dash);
  ctx.restore();
}

function drawAffected(
  ctx: CanvasRenderingContext2D,
  s: GuideSide,
  line: boolean,
  state: CoachState,
  lw: number,
  r: number,
  dash: number[],
): void {
  const colour = GUIDE_COLOR[state];
  // Rest position: thin.
  ctx.setLineDash([]);
  ctx.lineWidth = lw * 0.8;
  ctx.strokeStyle = GUIDE_COLOR.rest;
  path(ctx, s.rest, line, r * 0.8);
  // Goal: dashed, thick, green once reached.
  ctx.setLineDash(dash);
  ctx.lineWidth = lw * 1.6;
  ctx.strokeStyle = state === 'good' ? GUIDE_COLOR.good : GUIDE_COLOR.goal;
  path(ctx, s.goal, line, r * 1.25);
  ctx.setLineDash([]);
  // Arrow from rest towards the goal.
  ctx.lineWidth = lw;
  ctx.strokeStyle = state === 'good' ? GUIDE_COLOR.good : GUIDE_COLOR.goal;
  ctx.fillStyle = ctx.strokeStyle;
  arrow(ctx, centroid(s.rest), centroid(s.goal), r * 1.4);
  // Now: solid in the verdict colour.
  ctx.lineWidth = lw * 1.8;
  ctx.strokeStyle = colour;
  ctx.fillStyle = colour;
  if (line) path(ctx, s.now, true, r);
  dots(ctx, s.now, r * 0.7);
}

// ── Stretch guide (rehab/stretchGuide.ts) ───────────────────────────────

/** The fixing (blue) and stretching (orange) hands, the same colours as the illustration's hands. */
export const STRETCH_COLOR = { A: 'rgba(77,163,255,0.98)', B: 'rgba(255,153,51,0.98)' } as const;

/** Text on the canvas the CSS mirror would flip: drawn flipped back so it reads normally. */
function readableText(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, size: number, mirrored: boolean): void {
  ctx.save();
  ctx.translate(x, y);
  if (mirrored) ctx.scale(-1, 1);
  ctx.font = `700 ${size}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineWidth = Math.max(2, size / 5);
  ctx.strokeStyle = 'rgba(0,0,0,0.65)';
  ctx.strokeText(text, 0, 0);
  ctx.fillText(text, 0, 0);
  ctx.restore();
}

/** Draws the stretch contacts: blue rings where to hold, orange ring → arrow → full stretch, a dot for now, one label per hand. */
export function drawStretch(ctx: CanvasRenderingContext2D, marks: readonly StretchMark[], w: number, mirrored = true): void {
  const lw = Math.max(2, w / 300);
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  for (const hand of ['A', 'B'] as const) {
    const ms = marks.filter((m) => m.hand === hand);
    if (!ms.length) continue;
    // Several fingers of one hand sit close together: smaller rings so they stay apart.
    const r = Math.max(5, w / (ms.length > 1 ? 80 : 55));
    const colour = STRETCH_COLOR[hand];
    ctx.strokeStyle = colour;
    ctx.fillStyle = colour;
    for (const m of ms) {
      ctx.lineWidth = lw * 1.4;
      ctx.setLineDash(m.intraoral ? [lw * 2.5, lw * 2] : []);
      ctx.beginPath();
      ctx.arc(m.start.x, m.start.y, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
      if (!m.fixing) {
        ctx.setLineDash([lw * 3, lw * 2.4]);
        ctx.beginPath();
        ctx.arc(m.end.x, m.end.y, r * 0.8, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
        arrow(ctx, m.start, m.end, r * 0.9);
      }
      ctx.beginPath();
      ctx.arc(m.now.x, m.now.y, r * 0.45, 0, Math.PI * 2);
      ctx.fill();
    }
    // One label per hand, above the fixing hand and below the stretching one so the two do not collide.
    const c = centroid(ms.map((m) => m.start));
    const ys = ms.map((m) => m.start.y);
    const fixing = ms.every((m) => m.fixing);
    const size = Math.round(Math.max(11, w / 48));
    const y = fixing ? Math.min(...ys) - r - size * 0.9 : Math.max(...ys) + r + size * 0.9;
    const text = fixing ? '고정' : [...new Set(ms.map((m) => m.label))].join('·');
    ctx.fillStyle = 'rgba(255,255,255,0.98)';
    readableText(ctx, text, c.x, y, size, mirrored);
  }
  ctx.restore();
}

/** Warning colours for the region that must stay still, by synkinesis grade (SRS-RHB-022): orange → red → dark red. */
export const STILL_RGB: Record<1 | 2 | 3, readonly [number, number, number]> = {
  1: [255, 159, 28],
  2: [229, 56, 59],
  3: [139, 0, 0],
};

/**
 * The region that must stay still (affected eye or mouth corner), filled and outlined in the grade's colour while it
 * moves: a mild co-movement orange, a severe one dark red. Nothing at grade 0.
 */
export function drawStill(ctx: CanvasRenderingContext2D, still: GuideLines['still'], level: 0 | 1 | 2 | 3, w: number): void {
  if (!level || still.pts.length === 0) return;
  const [r, g, b] = STILL_RGB[level];
  const lw = Math.max(2, w / 260) * (1 + 0.35 * level);
  ctx.save();
  ctx.setLineDash([]);
  ctx.lineWidth = lw;
  ctx.strokeStyle = `rgba(${r},${g},${b},0.95)`;
  ctx.fillStyle = `rgba(${r},${g},${b},${0.22 + 0.12 * level})`;
  ctx.beginPath();
  if (still.region === 'eye') {
    // The eye outline, widened around its centre so the warning reads at a glance.
    const c = centroid(still.pts);
    still.pts.forEach((p, k) => {
      const q = { x: c.x + (p.x - c.x) * 1.45, y: c.y + (p.y - c.y) * 1.9 };
      if (k) ctx.lineTo(q.x, q.y);
      else ctx.moveTo(q.x, q.y);
    });
    ctx.closePath();
  } else {
    const p = still.pts[0]!;
    ctx.arc(p.x, p.y, Math.max(8, w / 26), 0, Math.PI * 2);
  }
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

/** Massage on the user's own face: the stroke path (dashed, with its direction) and where the fingertips are now. */
export function drawMassage(ctx: CanvasRenderingContext2D, m: { path: Vec2[]; at: Vec2 }, w: number): void {
  const lw = Math.max(2, w / 300);
  const r = Math.max(6, w / 55);
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.strokeStyle = STRETCH_COLOR.B;
  ctx.fillStyle = STRETCH_COLOR.B;
  ctx.lineWidth = lw * 1.4;
  ctx.setLineDash([lw * 3, lw * 2.4]);
  ctx.beginPath();
  m.path.forEach((p, k) => (k ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)));
  ctx.stroke();
  ctx.setLineDash([]);
  if (m.path.length > 1) arrow(ctx, m.path[m.path.length - 2]!, m.path[m.path.length - 1]!, r * 0.8);
  ctx.beginPath();
  ctx.arc(m.at.x, m.at.y, r, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(m.at.x, m.at.y, r * 0.45, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
