/**
 * Live movement guide for the exercise mirror (SRS-RHB-015): which points to move, how far, and whether the movement
 * is right, measured with the assessment core (SRS-RHB-005).
 *
 * Targets follow facial neuromuscular retraining (gentle, small, symmetric movements; no maximal effort), sized by how
 * much the affected side moved in the last assessment (SRS-RHB-031):
 * - a side that barely moves practises small movements with fine steps; a recovered one, larger movements;
 * - both sides aim at the same size (balance first, SRS-RHB-028): the healthy side's line is the affected side's goal;
 * - synkinesis during the exercise brings the goal below the size it appeared at, and the next session starts there.
 * Without an assessment the guide starts small (DEFAULT_SHARE of DEFAULT_RANGE) until one is made.
 */
import {
  ALIGNMENT_CANDIDATES,
  CHEEK_CONTOUR,
  LIP_MID_LOWER,
  LIP_MID_UPPER,
  SCORING,
  SIDE,
  fromFaceCoords,
  otherSide,
  outwardSign,
  restOnLive,
  type AnalysisResult,
  type FrameObservation,
  type FrameTaskValues,
  type LiveTaskId,
  type RestReference,
  type Side,
  type Vec2,
  voluntaryGrade,
} from '../core';

/**
 * Size of the practised movement (SRS-RHB-031), from the affected side's voluntary grade in the last assessment (the
 * assessment's own cuts, SCORING.voluntaryCuts): grade 1–2 small, 3 medium, 4–5 large; moderate or worse synkinesis in
 * that movement makes it one size smaller.
 */
export type EffortTier = 'small' | 'medium' | 'large';
/**
 * Per size, the goal: the last assessed ratio plus `step`, within [min, max]. For the symmetric movements these are
 * shares of the healthy side's assessed movement, which both sides aim at; for eye closure, shares of a full closure.
 * Small steps where the side barely moves (a reachable goal), larger movements near recovery but short of a maximal
 * effort. Provisional, for therapist review.
 */
export const TIER_GOAL: Record<EffortTier, { step: number; min: number; max: number }> = {
  small: { step: 0.05, min: 0.1, max: 0.45 },
  medium: { step: 0.1, min: 0.45, max: 0.75 },
  large: { step: 0.15, min: 0.75, max: 0.9 },
};
export const EYE_TIER_GOAL: Record<EffortTier, { step: number; min: number; max: number }> = {
  small: { step: 0.1, min: 0.15, max: 0.6 },
  medium: { step: 0.15, min: 0.4, max: 0.9 },
  large: { step: 0.15, min: 0.7, max: 1 },
};
/** The cheek puff (not assessed): the puff aimed at, as a share of DEFAULT_RANGE.cheekPuff, sized by the mouth. */
export const PUFF_SHARE: Record<EffortTier, number> = { small: 0.25, medium: 0.4, large: 0.6 };
/** Without an assessment the symmetric movements start at this share of DEFAULT_RANGE. */
export const DEFAULT_SHARE = 0.5;
/** Eye closure without an assessment: the share of a full closure aimed at. */
export const DEFAULT_GOAL = 0.6;
/**
 * The smallest goal (face units; eye closure: closure share): smaller movements are lost in the landmark jitter. At
 * calibration it also becomes at least NOISE_GOAL_Z rest-noise SDs of the affected side.
 */
export const GOAL_FLOOR: Record<LiveTaskId, number> = {
  brow: 0.008,
  eyeClose: 0.1,
  smile: 0.008,
  snarl: 0.005,
  pucker: 0.008,
  cheekPuff: 0.015,
};
export const NOISE_GOAL_Z = 4;
/** Synkinesis held during an exercise lowers the goal to this share of the movement it appeared at (SRS-RHB-031). */
export const CEIL_SHARE = 0.8;
/** The next session starts at most this much above the last session's lowered goal. */
export const CEIL_GROW = 1.1;
/** Typical comfortable range without an assessment (face units; eye closure as the closed share of the gap). */
export const DEFAULT_RANGE: Record<LiveTaskId, number> = {
  brow: 0.07,
  eyeClose: 1,
  smile: 0.065,
  snarl: 0.035,
  pucker: 0.06,
  // Provisional (no assessment measures it): a full puff pushes the cheek contour several millimetres out; the guide
  // is read mostly as the live ratio and the eye warning (SRS-RHB-022), so the ceiling only stops an extreme puff.
  cheekPuff: 0.12,
};
/** The healthy side moving this far past its comfortable range is too much. */
export const TOO_STRONG = 1.35;
/** Below this share of the goal the face counts as at rest (re-arms the rep counter). */
export const REST_SHARE = 0.25;
/** Seconds the goal must be held for a rep to count. */
export const HOLD_FOR_REP = 1;
/** A movement off rest shorter than this (and without a rep) is noise, not an attempt. */
export const MIN_ATTEMPT_SEC = 0.4;
/** Seconds of over-pulling or synkinesis within an attempt for it to count as such (one noisy frame does not). */
export const FLAG_SEC = 0.2;
/** Frames of movement needed before an exercise's median live ratio is kept (SRS-RHB-027). */
export const RATIO_MIN_FRAMES = 10;
/** Longest frame gap counted as time (a dropped camera frame or a background tab does not add seconds). */
const MAX_DT = 0.25;

/**
 * Small movements (SRS-RHB-019): the affected side this many rest-noise SDs above its rest level, held MICRO_SEC with
 * the healthy side quiet (below MICRO_HEALTHY_Z), so a pull from the healthy side's muscles does not count.
 */
export const MICRO_Z = 3;
export const MICRO_SEC = 0.5;
export const MICRO_HEALTHY_Z = 2;
/** Smallest rest-noise SD used (face units, about 0.13 mm): landmark jitter is never zero. */
export const NOISE_FLOOR = 0.002;
/** Tremor band (Hz) and the shortest stretch of movement it is measured on (research, SRS-RHB-019). */
export const SHAKE_BAND: readonly [number, number] = [4, 12];
export const SHAKE_MIN_SEC = 1.5;

/** The live measurement's jitter on a still face, per side (from the guide's 2 s calibration). */
export interface RestNoise {
  mean: Record<Side, number>;
  sd: Record<Side, number>;
  n: number;
}

const median = (xs: readonly number[]) => {
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
};

/**
 * Rest level and spread of each side's excursion over still frames: median and MAD (robust to a blink), inflated a
 * quarter because the frames also made the reference they are measured against, and never below NOISE_FLOOR.
 */
export function restNoise(samples: readonly FrameTaskValues[]): RestNoise | null {
  if (samples.length < 5) return null;
  const side = (k: Side) => {
    const xs = samples.map((v) => v.excursion[k]);
    const m = median(xs);
    return { m, sd: Math.max(NOISE_FLOOR, 1.25 * 1.4826 * median(xs.map((x) => Math.abs(x - m)))) };
  };
  const l = side('left');
  const r = side('right');
  return { mean: { left: l.m, right: r.m }, sd: { left: l.sd, right: r.sd }, n: samples.length };
}

/**
 * Oscillation in the tremor band of a movement trace, against what the rest noise alone would put there (1 = only
 * noise). Resampled to an even rate; null when too short or the camera too slow for the band.
 */
export function shakeRatio(trace: readonly { t: number; x: number }[], noiseSd: number): number | null {
  if (trace.length < 8) return null;
  const span = trace[trace.length - 1]!.t - trace[0]!.t;
  if (span < SHAKE_MIN_SEC) return null;
  const dts = trace
    .slice(1)
    .map((p, i) => p.t - trace[i]!.t)
    .filter((d) => d > 0);
  const fs = 1 / median(dts);
  const hi = Math.min(SHAKE_BAND[1], fs / 2 - 1);
  if (hi <= SHAKE_BAND[0] + 1) return null;
  const n = Math.floor(span * fs);
  const xs: number[] = [];
  for (let k = 0, j = 0; k < n; k++) {
    const t = trace[0]!.t + k / fs;
    while (j < trace.length - 2 && trace[j + 1]!.t < t) j++;
    const a = trace[j]!;
    const b = trace[j + 1]!;
    xs.push(b.t > a.t ? a.x + ((b.x - a.x) * (t - a.t)) / (b.t - a.t) : a.x);
  }
  // Take out the slow voluntary movement with a straight line, then add up the band of the spectrum.
  const tm = (n - 1) / 2;
  const xm = xs.reduce((sum, x) => sum + x, 0) / n;
  let sxy = 0;
  let sxx = 0;
  xs.forEach((x, k) => {
    sxy += (k - tm) * (x - xm);
    sxx += (k - tm) ** 2;
  });
  const slope = sxx > 0 ? sxy / sxx : 0;
  const d = xs.map((x, k) => x - xm - slope * (k - tm));
  let band = 0;
  for (let f = 1; f < n / 2; f++) {
    const hz = (f * fs) / n;
    if (hz < SHAKE_BAND[0] || hz > hi) continue;
    let re = 0;
    let im = 0;
    d.forEach((x, k) => {
      re += x * Math.cos((2 * Math.PI * f * k) / n);
      im -= x * Math.sin((2 * Math.PI * f * k) / n);
    });
    band += (2 * (re * re + im * im)) / (n * n);
  }
  // White noise of SD s puts s² × bandwidth / (fs / 2) into the band.
  const expected = noiseSd ** 2 * ((hi - SHAKE_BAND[0]) / (fs / 2));
  return Math.sqrt(band / expected);
}
/** Smile direction: up and outward, this many degrees above horizontal (zygomaticus major). */
const SMILE_DEG = 40;

export interface GuidePlan {
  task: LiveTaskId;
  /**
   * The healthy side's line (face units; eyeClose: closure share). For the symmetric movements and the cheek puff it is
   * the goal size itself, which both sides aim at; for eye closure, a full closure.
   */
  range: number;
  /** The affected side's goal as a share of `range` (1 where both sides aim at the same size). */
  goal: number;
  source: 'assessment' | 'default';
  /** The last assessed ratio the goal steps from (assessment source only). */
  lastRatio?: number;
  /** Size of the practised movement (SRS-RHB-031); unset in plans made before it (= medium). */
  tier?: EffortTier;
  /** The goal as a share of the healthy side's assessed movement (symmetric movements with an assessment). */
  share?: number;
  /** The goal was lowered below where synkinesis appeared (this session or the last one). */
  lowered?: boolean;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** The movement size for a last assessed ratio and that movement's synkinesis grade (SRS-RHB-031). */
export function effortTier(ratio: number, synkGrade = 0): EffortTier {
  const g = voluntaryGrade(ratio);
  const t: EffortTier = g <= 2 ? 'small' : g === 3 ? 'medium' : 'large';
  return synkGrade >= 2 ? (t === 'large' ? 'medium' : 'small') : t;
}

/**
 * Targets from the latest assessment that measured this task reliably, else a small start. `prevCeil` is the goal the
 * last session of this task lowered to for synkinesis (absolute); this one starts no more than CEIL_GROW above it.
 */
export function guidePlan(task: LiveTaskId, last: AnalysisResult | null | undefined, affected: Side, prevCeil?: number): GuidePlan {
  const plan = basePlan(task, last, affected);
  return prevCeil === undefined ? plan : capPlan(plan, Math.max(GOAL_FLOOR[task], prevCeil * CEIL_GROW));
}

function basePlan(task: LiveTaskId, last: AnalysisResult | null | undefined, affected: Side): GuidePlan {
  const healthy = otherSide(affected);
  const usable = (t: Exclude<LiveTaskId, 'cheekPuff'>) => {
    const m = last?.tasks[t];
    return m && m.reliable && m.excursion[healthy] >= SCORING.minHealthyExcursion[t] ? m : undefined;
  };
  if (task === 'cheekPuff') {
    // Not assessed: sized by the mouth (the weaker of smile and pucker); without them, small. The puff is the goal
    // for both cheeks, so its line is also where too much air begins.
    const ratios = (['smile', 'pucker'] as const).flatMap((t) => usable(t)?.ratio ?? []);
    const tier = ratios.length ? effortTier(Math.min(...ratios)) : 'small';
    return { task, range: PUFF_SHARE[tier] * DEFAULT_RANGE.cheekPuff, goal: 1, source: 'default', tier };
  }
  const m = usable(task);
  if (m) {
    const tier = effortTier(m.ratio, m.synkinesisGrade ?? 0);
    if (task === 'eyeClose') {
      // The clinical aim is a complete gentle closure, whatever the healthy eye's squeeze.
      const e = EYE_TIER_GOAL[tier];
      return { task, range: 1, goal: clamp(m.ratio + e.step, e.min, e.max), source: 'assessment', lastRatio: m.ratio, tier };
    }
    const t = TIER_GOAL[tier];
    const share = clamp(m.ratio + t.step, t.min, t.max);
    return {
      task,
      range: Math.max(GOAL_FLOOR[task], share * m.excursion[healthy]),
      goal: 1,
      source: 'assessment',
      lastRatio: m.ratio,
      tier,
      share,
    };
  }
  if (task === 'eyeClose') return { task, range: 1, goal: DEFAULT_GOAL, source: 'default', tier: 'small' };
  return { task, range: DEFAULT_SHARE * DEFAULT_RANGE[task], goal: 1, source: 'default', tier: 'small' };
}

/** The plan with its goal no bigger than `abs` (face units; eye closure: closure share); the same plan if it already is. */
export function capPlan(plan: GuidePlan, abs: number): GuidePlan {
  if (abs >= plan.goal * plan.range - 1e-12) return plan;
  // Where both sides aim at the goal the healthy side's line comes down with it; eye closure keeps a full closure.
  return plan.task === 'eyeClose' ? { ...plan, goal: abs / plan.range, lowered: true } : { ...plan, range: abs / plan.goal, lowered: true };
}

/** The plan with its goal at least `abs` (a goal smaller than the jitter cannot be seen). */
function floorPlan(plan: GuidePlan, abs: number): GuidePlan {
  if (abs <= plan.goal * plan.range) return plan;
  return plan.task === 'eyeClose' ? { ...plan, goal: Math.min(1, abs) } : { ...plan, range: abs / plan.goal };
}

export type CoachState = 'rest' | 'move' | 'good' | 'tooStrong' | 'synk' | 'unbalanced';
/** Which way an unbalanced movement leans: the affected side ahead, the healthy side ahead, or the mouth pulled sideways. */
export type Lead = 'affected' | 'healthy' | 'shift';

/**
 * Balance first (SRS-RHB-028), as facial neuromuscular retraining teaches: small symmetric movements, the healthy side
 * held back to the affected side's size, the affected side's range grown without synkinesis. A good repetition needs
 * the smaller side at least BALANCE_MIN of the larger; an imbalance is called once the larger side passes BALANCE_FROM
 * of the goal (a movement starts unevenly). Eye closure and the cheek puff are left out: a healthy eye closes fully,
 * and puffed air presses on both cheeks alike.
 */
export const BALANCE_MIN = 0.75;
export const BALANCE_FROM = 0.5;
/** The mouth pulled sideways this far (face units, about 3 mm) in a pucker or a smile is not a symmetric movement. */
export const LIP_SHIFT_MAX = 0.05;
export const isBalancedTask = (task: LiveTaskId): boolean => task !== 'eyeClose' && task !== 'cheekPuff';

export interface CoachFrame {
  state: CoachState;
  /** Affected-side movement as a share of its goal (1 = goal reached). */
  progress: number;
  /** Healthy-side movement as a share of the comfortable range (1 = ceiling). */
  healthyLoad: number;
  /**
   * Synkinesis now (SRS-RHB-022): the off-target region's movement on the affected side beyond the healthy side's (the
   * assessment's synkinesis index), and its grade on the assessment's cuts (0 none, 1 mild … 3 severe).
   */
  synkIndex: number;
  synkLevel: SynkLevel;
  /** The smaller side's movement over the larger's while moving (1 = equal; 1 at rest). */
  balance: number;
  /** Set while unbalanced: which way it leans. */
  lead: Lead | null;
}

export type SynkLevel = 0 | 1 | 2 | 3;

/** The region that must stay still in a task: the eye (mouth and cheek movements) or the mouth corner (brow, eye). */
export const offTargetRegion = (task: LiveTaskId): 'eye' | 'mouth' => (task === 'brow' || task === 'eyeClose' ? 'mouth' : 'eye');

/** The synkinesis cuts the assessment uses for this task's off-target region (scoring.ts). */
export const synkCuts = (task: LiveTaskId) => (offTargetRegion(task) === 'mouth' ? SCORING.synkMouthCuts : SCORING.synkEyeCuts);

/** Grade 0–3 of a synkinesis index on the task's cuts. */
export const synkLevelOf = (task: LiveTaskId, index: number): SynkLevel => synkCuts(task).filter((c) => index > c).length as SynkLevel;

/**
 * One frame's verdict, most important first: synkinesis on the affected side (stop and move smaller), then a healthy
 * side pulling past its comfortable range, then the goal reached.
 */
export function coachFrame(task: LiveTaskId, v: FrameTaskValues, affected: Side, plan: GuidePlan): CoachFrame {
  const healthy = otherSide(affected);
  const progress = Math.max(0, v.excursion[affected]) / (plan.goal * plan.range);
  const healthyLoad = Math.max(0, v.excursion[healthy]) / plan.range;
  const moving = progress >= REST_SHARE || healthyLoad >= REST_SHARE;
  // As the assessment: the affected side's off-target movement beyond the healthy side's (both eyes narrowing in a
  // broad smile is not synkinesis).
  const synkIndex = Math.max(0, v.offTarget[affected] - v.offTarget[healthy]);
  const synkLevel = moving ? synkLevelOf(task, synkIndex) : 0;
  return { progress, healthyLoad, synkIndex, synkLevel, ...verdict(task, plan, progress, healthyLoad, v.extras.lipShift ?? 0, synkLevel) };
}

/**
 * The verdict, most important first: synkinesis, the healthy side past its comfortable range, an unbalanced movement
 * (or the mouth pulled sideways), the goal reached in balance, moving, rest.
 */
function verdict(
  task: LiveTaskId,
  plan: GuidePlan,
  progress: number,
  healthyLoad: number,
  lipShift: number,
  synkLevel: SynkLevel,
): { state: CoachState; balance: number; lead: Lead | null } {
  const a = progress * plan.goal * plan.range;
  const h = healthyLoad * plan.range;
  const moving = progress >= REST_SHARE || healthyLoad >= REST_SHARE;
  const balance = moving && Math.max(a, h) > 1e-9 ? Math.min(a, h) / Math.max(a, h) : 1;
  const shifted = (task === 'pucker' || task === 'smile') && Math.abs(lipShift) > LIP_SHIFT_MAX;
  const leaning = isBalancedTask(task) && Math.max(a, h) >= BALANCE_FROM * plan.goal * plan.range && balance < BALANCE_MIN;
  let state: CoachState;
  if (synkLevel > 0) state = 'synk';
  else if (healthyLoad > TOO_STRONG) state = 'tooStrong';
  else if (moving && (shifted || leaning)) state = 'unbalanced';
  else if (progress >= 1) state = 'good';
  else if (moving) state = 'move';
  else state = 'rest';
  const lead: Lead | null = state !== 'unbalanced' ? null : shifted ? 'shift' : a >= h ? 'affected' : 'healthy';
  return { state, balance, lead };
}

/**
 * The healthy side against the affected side, for the bar's words (SRS-RHB-028/031): about the same size is right;
 * it is not "the less the better". `early` = too soon in the movement to judge; cheek puff and eye closure only say
 * when the healthy side does too much.
 */
export function healthyMatch(
  task: LiveTaskId,
  plan: GuidePlan,
  progress: number,
  healthyLoad: number,
): 'rest' | 'early' | 'match' | 'less' | 'more' {
  if (progress < REST_SHARE && healthyLoad < REST_SHARE) return 'rest';
  if (healthyLoad > TOO_STRONG) return 'less';
  if (!isBalancedTask(task)) return 'match';
  const a = progress * plan.goal;
  if (Math.max(a, healthyLoad) < BALANCE_FROM * plan.goal) return 'early';
  if (healthyLoad > a / BALANCE_MIN) return 'less';
  if (healthyLoad < a * BALANCE_MIN) return 'more';
  return 'match';
}

/** What to do about an unbalanced movement (SRS-RHB-028). */
export function balanceText(task: LiveTaskId, lead: Lead): string {
  if (lead === 'shift')
    return task === 'pucker' ? '입을 한쪽으로 당기지 말고 가운데로 모으세요' : '입꼬리를 한쪽으로 끌지 말고 양쪽 똑같이 올리세요';
  return lead === 'healthy' ? '건강한 쪽을 마비 쪽 크기에 맞춰 줄이세요' : '양쪽을 똑같이 움직이세요. 건강한 쪽도 같이 조금';
}

/** What the timeline does with the live guide's verdict (SRS-RHB-029). */
export type GateAction = 'none' | 'pause' | 'play' | 'toHold' | 'toRelease';
/** A hold that does not come within this long moves on to the release. */
export const HOLD_WAIT_MS = 8000;
/** Back at rest this long during the hold = let go: the hold ends into the release. */
export const LET_GO_MS = 700;

/**
 * Movement-gated hold (SRS-RHB-029): hold time counts only while the goal is held (in balance); reaching it while still
 * moving starts the hold at once; letting go ends it into the release; waiting HOLD_WAIT_MS for it moves on.
 */
export function holdGate(phase: string, state: CoachState, g: { pausedByGate: boolean; restMs: number; waitMs: number }): GateAction {
  if (phase === 'stretch') return state === 'good' ? 'toHold' : g.pausedByGate ? 'play' : 'none';
  if (phase !== 'hold') return g.pausedByGate ? 'play' : 'none';
  if (state === 'good') return g.pausedByGate ? 'play' : 'none';
  if (state === 'rest' && g.restMs >= LET_GO_MS) return 'toRelease';
  if (g.pausedByGate) return g.waitMs >= HOLD_WAIT_MS ? 'toRelease' : 'none';
  return 'pause';
}

/**
 * What to do when the region that must stay still moves, by task and grade (SRS-RHB-022): mild → do a little less,
 * moderate → smaller and slower, severe → stop and relax first. The cheek puff is said in its own terms (the air).
 */
export function synkText(task: LiveTaskId, level: SynkLevel): string {
  if (task === 'cheekPuff')
    return level >= 2
      ? '눈이 너무 많이 감깁니다. 바람의 양을 줄이고, 눈은 일부러 뜬 채로 눈 감김을 최소화해 주세요'
      : '눈이 조금 작아져요. 바람을 조금 줄이고 눈을 뜬 채로 두세요';
  const eye = offTargetRegion(task) === 'eye';
  if (level >= 3) return `${eye ? '눈이 너무 많이 감깁니다' : '입꼬리가 너무 많이 움직입니다'}. 잠시 멈추고 힘을 뺀 뒤 더 작게 하세요`;
  if (level === 2) return `${eye ? '눈이 같이 감겨요. 눈은 뜬 채로' : '입꼬리가 같이 움직여요'}. 더 작고 천천히 하세요`;
  return `${eye ? '눈이 조금 같이 작아져요. 눈을 뜬 채로' : '입꼬리가 조금 같이 움직여요'}. 동작을 조금 줄여 보세요`;
}

/** How one guided exercise went (SRS-RHB-018): attempts and how many were right, too strong or synkinetic. */
export interface BioQuality {
  /** Movements off rest (each ends back near rest). */
  attempts: number;
  /** Attempts that held the goal HOLD_FOR_REP seconds. */
  reps: number;
  /** Attempts where the healthy side pulled past TOO_STRONG for FLAG_SEC. */
  tooStrong: number;
  /** Attempts with synkinesis on the affected side for FLAG_SEC. */
  synk: number;
  /** Highest synkinesis grade held FLAG_SEC (1 mild … 3 severe; SRS-RHB-022). */
  synkMax?: SynkLevel;
  /** Attempts by their highest synkinesis grade held FLAG_SEC: [mild, moderate, severe] (SRS-RHB-030). */
  synkGrades?: [number, number, number];
  /** Attempts unbalanced (or the mouth pulled sideways) for FLAG_SEC (SRS-RHB-028). */
  unbalanced?: number;
  /** Median balance (smaller side over larger) while moving, balanced tasks only (SRS-RHB-030). */
  balanceMed?: number;
  /**
   * Median affected / healthy while moving (SRS-RHB-027), with at least RATIO_MIN_FRAMES frames. An exercise-time
   * observation, not the assessment's ratio: the movements are kept small on purpose.
   */
  ratioMed?: number;
  /** Seconds at the goal, and moving at all. */
  goodSec: number;
  activeSec: number;
  /** Longest hold at the goal (s). */
  heldMax: number;
  /** Best smoothed progress (share of the goal, ≤ 2). */
  best: number;
  /** Small movements seen with the healthy side quiet (SRS-RHB-019), and their seconds; with a rest-noise model only. */
  microEvents?: number;
  microSec?: number;
  /** Largest tremor-band ratio over the attempts (research, not validated; 1 = rest noise only). */
  shake?: number;
  /** The affected side's rest noise SD (face units): how precise this session's live measurement was. */
  noiseSd?: number;
  /** The goal the guide lowered to for synkinesis (absolute, as the plan's units) and how many times (SRS-RHB-031). */
  synkCeil?: number;
  lowered?: number;
}

/**
 * Counts good repetitions: the goal held for HOLD_FOR_REP seconds counts once, and the next one needs the face back
 * near rest first. Frames are smoothed (EMA) so one noisy frame neither breaks a hold nor fakes one. Each movement
 * off rest is an attempt; quality() says how many were right, too strong on the healthy side, or synkinetic.
 */
export class RepCounter {
  reps = 0;
  /** Best smoothed progress so far. */
  best = 0;
  private goodSince: number | null = null;
  private armed = true;
  private ema: { progress: number; healthyLoad: number; synk: number; shift: number } | null = null;
  private synkHeld: { level: SynkLevel; since: number } | null = null;
  private synkMax: SynkLevel = 0;
  private ratios: number[] = [];
  private balances: number[] = [];
  private grades: [number, number, number] = [0, 0, 0];
  private unbal = 0;
  private lastT: number | null = null;
  private done = { attempts: 0, tooStrong: 0, synk: 0 };
  private goodSec = 0;
  private activeSec = 0;
  private heldMax = 0;
  /** The attempt under way: seconds moving, over-pulling, synkinetic, whether it made a rep, and its trace. */
  private cur: {
    sec: number;
    strongSec: number;
    synkSec: number;
    unbalSec: number;
    synkLv: SynkLevel;
    rep: boolean;
    trace: { t: number; x: number }[];
  } | null = null;
  private noise: RestNoise | null = null;
  private zEma: { aff: number; healthy: number } | null = null;
  private microSince: number | null = null;
  private microArmed = true;
  private micro = { events: 0, sec: 0 };
  private shakeMax: number | null = null;
  private plan: GuidePlan;
  private floor: number;
  private ceil: number | null = null;
  private lowerings = 0;

  constructor(
    private readonly task: LiveTaskId,
    private readonly affected: Side,
    plan: GuidePlan,
    private readonly alpha = 0.45,
  ) {
    this.floor = GOAL_FLOOR[task];
    this.plan = floorPlan(plan, this.floor);
  }

  /** The plan in use: the goal may have come down for synkinesis (SRS-RHB-031) or up to what can be seen. */
  get currentPlan(): GuidePlan {
    return this.plan;
  }

  /**
   * Sets the rest noise (from the calibration frames, restNoise) that small movements and tremor are judged against;
   * a goal within NOISE_GOAL_Z SDs of it could not be told from the jitter, so it is raised to that.
   */
  setNoise(n: RestNoise | null): void {
    this.noise = n;
    this.floor = Math.max(GOAL_FLOOR[this.task], NOISE_GOAL_Z * (n?.sd[this.affected] ?? 0));
    this.plan = floorPlan(this.plan, this.floor);
  }

  /** Brings the goal down to `abs` (not below the floor), keeping the smoothed values in the new units. */
  private lowerTo(abs: number): boolean {
    const next = capPlan(this.plan, Math.max(this.floor, abs));
    if (next === this.plan) return false;
    const was = { goal: this.plan.goal * this.plan.range, range: this.plan.range };
    const now = { goal: next.goal * next.range, range: next.range };
    if (this.ema)
      this.ema = {
        ...this.ema,
        progress: (this.ema.progress * was.goal) / now.goal,
        healthyLoad: (this.ema.healthyLoad * was.range) / now.range,
      };
    this.best = Math.min(2, (this.best * was.goal) / now.goal);
    this.plan = next;
    this.ceil = now.goal;
    this.lowerings += 1;
    return true;
  }

  /**
   * Feeds one measured frame at time `t` (seconds); returns the smoothed verdict, hold time, whether a rep counted, the
   * smoothed synkinesis grade for the warning (SRS-RHB-022) and the live ratio affected / healthy (null while the
   * healthy side is near rest).
   */
  update(
    v: FrameTaskValues,
    t: number,
  ): CoachFrame & { held: number; counted: boolean; reps: number; micro: boolean; ratio: number | null; lowered: boolean } {
    const raw = coachFrame(this.task, v, this.affected, this.plan);
    const a = this.alpha;
    this.ema = this.ema
      ? {
          progress: this.ema.progress + a * (raw.progress - this.ema.progress),
          healthyLoad: this.ema.healthyLoad + a * (raw.healthyLoad - this.ema.healthyLoad),
          synk: this.ema.synk + a * (raw.synkIndex - this.ema.synk),
          shift: this.ema.shift + a * ((v.extras.lipShift ?? 0) - this.ema.shift),
        }
      : { progress: raw.progress, healthyLoad: raw.healthyLoad, synk: raw.synkIndex, shift: v.extras.lipShift ?? 0 };
    const { progress, healthyLoad } = this.ema;
    const synkIndex = this.ema.synk;
    // The warning follows the smoothed index (no flicker); at rest there is nothing to warn about.
    const synkLevel: SynkLevel = raw.state === 'rest' ? 0 : synkLevelOf(this.task, synkIndex);
    const ratio = healthyLoad >= REST_SHARE ? (progress * this.plan.goal) / healthyLoad : null;
    // Synkinesis keeps the raw verdict: it should stop the hold at once. The rest follows the smoothed values.
    const vd = verdict(this.task, this.plan, progress, healthyLoad, this.ema.shift, raw.state === 'synk' ? raw.synkLevel || 1 : 0);
    const state: CoachState = vd.state;
    this.best = Math.max(this.best, Math.min(progress, 2));
    const dt = this.lastT === null ? 0 : clamp(t - this.lastT, 0, MAX_DT);
    this.lastT = t;
    let counted = false;
    let lowered = false;
    let held = 0;
    if (state === 'good') {
      this.goodSince ??= t;
      held = t - this.goodSince;
      this.goodSec += dt;
      this.heldMax = Math.max(this.heldMax, held);
      if (this.armed && held >= HOLD_FOR_REP) {
        this.reps += 1;
        this.armed = false;
        counted = true;
      }
    } else {
      this.goodSince = null;
      if (progress < REST_SHARE) this.armed = true;
    }
    const micro = this.updateMicro(v, t, dt, state);
    // The worst grade held FLAG_SEC (one noisy frame does not make a severe warning).
    let heldGrade: SynkLevel = 0;
    if (synkLevel > 0) {
      if (!this.synkHeld || synkLevel !== this.synkHeld.level) this.synkHeld = { level: synkLevel, since: t };
      if (t - this.synkHeld.since >= FLAG_SEC) {
        heldGrade = this.synkHeld.level;
        this.synkMax = Math.max(this.synkMax, heldGrade) as SynkLevel;
      }
    } else this.synkHeld = null;
    if (state === 'rest') this.endAttempt();
    else {
      this.cur ??= { sec: 0, strongSec: 0, synkSec: 0, unbalSec: 0, synkLv: 0, rep: false, trace: [] };
      this.cur.sec += dt;
      this.activeSec += dt;
      if (state === 'tooStrong') this.cur.strongSec += dt;
      if (raw.state === 'synk') this.cur.synkSec += dt;
      if (state === 'unbalanced') this.cur.unbalSec += dt;
      // Synkinesis held in this attempt for the first time: the goal goes below the size it appeared at (SRS-RHB-031).
      // The size is the larger side's movement (both sides aim at the goal); for eye closure, the affected eye's.
      if (heldGrade > 0 && this.cur.synkLv === 0) {
        const a = progress * this.plan.goal * this.plan.range;
        const h = healthyLoad * this.plan.range;
        lowered = this.lowerTo(CEIL_SHARE * (this.task === 'eyeClose' ? a : Math.max(a, h)));
      }
      if (heldGrade > this.cur.synkLv) this.cur.synkLv = heldGrade;
      if (isBalancedTask(this.task)) this.balances.push(vd.balance);
      if (counted) this.cur.rep = true;
      if (this.noise) this.cur.trace.push({ t, x: v.excursion[this.affected] });
    }
    if (ratio !== null && state !== 'rest') this.ratios.push(ratio);
    return {
      state,
      progress,
      healthyLoad,
      held,
      counted,
      reps: this.reps,
      micro,
      synkIndex,
      synkLevel,
      ratio,
      balance: vd.balance,
      lead: vd.lead,
      lowered,
    };
  }

  /** Small movement: the affected side clearly above its rest noise while the healthy side stays still. */
  private updateMicro(v: FrameTaskValues, t: number, dt: number, state: CoachState): boolean {
    const n = this.noise;
    if (!n) return false;
    const healthy = otherSide(this.affected);
    const z = {
      aff: (v.excursion[this.affected] - n.mean[this.affected]) / n.sd[this.affected],
      healthy: (v.excursion[healthy] - n.mean[healthy]) / n.sd[healthy],
    };
    const a = this.alpha;
    this.zEma = this.zEma
      ? { aff: this.zEma.aff + a * (z.aff - this.zEma.aff), healthy: this.zEma.healthy + a * (z.healthy - this.zEma.healthy) }
      : z;
    const on = this.zEma.aff >= MICRO_Z && this.zEma.healthy < MICRO_HEALTHY_Z && (state === 'rest' || state === 'move');
    if (!on) {
      this.microSince = null;
      if (this.zEma.aff < MICRO_Z / 2) this.microArmed = true;
      return false;
    }
    this.microSince ??= t;
    if (t - this.microSince < MICRO_SEC) return false;
    this.micro.sec += dt;
    if (this.microArmed) {
      this.micro.events += 1;
      this.microArmed = false;
    }
    return true;
  }

  private endAttempt(): void {
    const c = this.cur;
    this.cur = null;
    if (!c || (c.sec < MIN_ATTEMPT_SEC && !c.rep)) return;
    this.noteShake(c.trace);
    this.done.attempts += 1;
    if (c.strongSec >= FLAG_SEC) this.done.tooStrong += 1;
    if (c.synkSec >= FLAG_SEC) this.done.synk += 1;
    if (c.unbalSec >= FLAG_SEC) this.unbal += 1;
    if (c.synkLv > 0) this.grades[c.synkLv - 1]! += 1;
  }

  private noteShake(trace: readonly { t: number; x: number }[]): void {
    if (!this.noise) return;
    const r = shakeRatio(trace, this.noise.sd[this.affected]);
    if (r !== null) this.shakeMax = Math.max(this.shakeMax ?? 0, r);
  }

  /** The exercise so far; an attempt still under way counts if it would count on ending now. */
  quality(): BioQuality {
    const c = this.cur;
    const open = !!c && (c.sec >= MIN_ATTEMPT_SEC || c.rep);
    const r1 = (x: number) => Math.round(x * 10) / 10;
    const openShake = open && this.noise ? shakeRatio(c!.trace, this.noise.sd[this.affected]) : null;
    const shake = openShake === null ? this.shakeMax : Math.max(this.shakeMax ?? 0, openShake);
    const extra = this.noise
      ? {
          microEvents: this.micro.events,
          microSec: r1(this.micro.sec),
          ...(shake !== null ? { shake: r1(shake) } : {}),
          noiseSd: Math.round(this.noise.sd[this.affected] * 10000) / 10000,
        }
      : {};
    return {
      attempts: this.done.attempts + (open ? 1 : 0),
      reps: this.reps,
      tooStrong: this.done.tooStrong + (open && c!.strongSec >= FLAG_SEC ? 1 : 0),
      synk: this.done.synk + (open && c!.synkSec >= FLAG_SEC ? 1 : 0),
      ...(this.synkMax ? { synkMax: this.synkMax } : {}),
      synkGrades: [
        this.grades[0] + (open && c!.synkLv === 1 ? 1 : 0),
        this.grades[1] + (open && c!.synkLv === 2 ? 1 : 0),
        this.grades[2] + (open && c!.synkLv === 3 ? 1 : 0),
      ],
      unbalanced: this.unbal + (open && c!.unbalSec >= FLAG_SEC ? 1 : 0),
      ...(this.balances.length >= RATIO_MIN_FRAMES ? { balanceMed: Math.round(median(this.balances) * 100) / 100 } : {}),
      ...(this.ratios.length >= RATIO_MIN_FRAMES ? { ratioMed: Math.round(median(this.ratios) * 100) / 100 } : {}),
      goodSec: r1(this.goodSec),
      activeSec: r1(this.activeSec),
      heldMax: r1(this.heldMax),
      best: Math.round(this.best * 100) / 100,
      ...(this.ceil !== null ? { synkCeil: Math.round(this.ceil * 10000) / 10000, lowered: this.lowerings } : {}),
      ...extra,
    };
  }
}

/**
 * Face points the live guide needs tracked for a task (SRS-RHB-026): the alignment candidates the measurement aligns
 * on, the moving points, the measured ones and the region that must stay still, on both sides. About 60–80 of the 468,
 * which keeps tracking fast enough for a phone; the others keep the detection.
 */
export function liveTrackPoints(task: LiveTaskId): ReadonlySet<number> {
  const out = new Set<number>(ALIGNMENT_CANDIDATES);
  for (const side of ['left', 'right'] as const) {
    const s = SIDE[side];
    guidePoints(task, side).forEach((i) => out.add(i));
    s.lidPairs.flat().forEach((i) => out.add(i));
    [...s.upperLid, ...s.lowerLid, s.mouthCorner].forEach((i) => out.add(i));
    if (task === 'brow') s.brow.forEach((i) => out.add(i));
  }
  out.add(LIP_MID_UPPER);
  out.add(LIP_MID_LOWER);
  return out;
}

/** The landmark set each task moves, per side (core/landmarks.ts). */
export function guidePoints(task: LiveTaskId, side: Side): readonly number[] {
  const s = SIDE[side];
  switch (task) {
    case 'cheekPuff':
      return CHEEK_CONTOUR[side];
    case 'brow':
      return s.brow;
    case 'eyeClose':
      return s.upperLid;
    case 'smile':
    case 'pucker':
      return [s.mouthCorner];
    case 'snarl':
      return [...s.ala, ...s.upperLip];
  }
}

/** Where the task's points go when moved by `amount` (face units; eyeClose: share of the lid gap closed). */
function moved(task: LiveTaskId, side: Side, rest: readonly Vec2[], amount: number): Vec2[] {
  const idx = guidePoints(task, side);
  const out = outwardSign(side);
  switch (task) {
    case 'cheekPuff':
      return idx.map((i) => ({ x: rest[i]!.x + out * amount, y: rest[i]!.y }));
    case 'brow':
    case 'snarl':
      return idx.map((i) => ({ x: rest[i]!.x, y: rest[i]!.y - amount }));
    case 'eyeClose': {
      const lower = SIDE[side].lowerLid;
      return idx.map((i, k) => {
        const u = rest[i]!;
        const l = rest[lower[k]!]!;
        return { x: u.x + (l.x - u.x) * amount, y: u.y + (l.y - u.y) * amount };
      });
    }
    case 'smile': {
      const th = (SMILE_DEG * Math.PI) / 180;
      return idx.map((i) => ({ x: rest[i]!.x + out * Math.cos(th) * amount, y: rest[i]!.y - Math.sin(th) * amount }));
    }
    case 'pucker':
      return idx.map((i) => ({ x: rest[i]!.x - out * amount, y: rest[i]!.y }));
  }
}

export interface GuideSide {
  /** The points at rest, where they are now, and where they should go (live image pixels). */
  rest: Vec2[];
  now: Vec2[];
  goal: Vec2[];
}

export interface GuideLines {
  task: LiveTaskId;
  affected: GuideSide;
  /** For the healthy side `goal` is the ceiling of its comfortable range. */
  healthy: GuideSide;
  /** Points form a line (brow, upper lid, cheek contour) or stand alone (mouth corner, nose and lip points). */
  line: boolean;
  /**
   * The region that must stay still, on the affected side, in live pixels (SRS-RHB-022): the eye's outline (upper
   * then lower lid) or the mouth corner.
   */
  still: { region: 'eye' | 'mouth'; pts: Vec2[] };
}

/** The guide drawn over one live frame: rest, current and goal positions of the task's points on both sides. */
export function guideLines(
  task: LiveTaskId,
  ref: RestReference,
  obs: FrameObservation,
  affected: Side,
  plan: GuidePlan,
): GuideLines | null {
  const healthy = otherSide(affected);
  const goalAff = moved(task, affected, ref.face, plan.goal * plan.range);
  const ceiling = moved(task, healthy, ref.face, plan.range);
  const mapped = restOnLive(ref, obs, fromFaceCoords(ref.frame, [...goalAff, ...ceiling]));
  if (!mapped) return null;
  const side = (s: Side, goal: Vec2[]): GuideSide => {
    const idx = guidePoints(task, s);
    return { rest: idx.map((i) => mapped.rest[i]!), now: idx.map((i) => mapped.live[i]!), goal };
  };
  const region = offTargetRegion(task);
  const a = SIDE[affected];
  const stillIdx = region === 'eye' ? [...a.upperLid, ...[...a.lowerLid].reverse()] : [a.mouthCorner];
  return {
    task,
    affected: side(affected, mapped.extra.slice(0, goalAff.length)),
    healthy: side(healthy, mapped.extra.slice(goalAff.length)),
    line: task === 'brow' || task === 'eyeClose' || task === 'cheekPuff',
    still: { region, pts: stillIdx.map((i) => mapped.live[i]!) },
  };
}
