/**
 * Korean particles that depend on the last syllable of the word before them: 을/를, 이/가, 은/는, 과/와, 으로/로.
 * A trailing (note) is skipped, since it is read after the word: 엄지(입안)를.
 */
export type JosaPair = '을/를' | '이/가' | '은/는' | '과/와' | '으로/로';

/** The final consonant index of the last Hangul syllable (0 = none, 8 = ㄹ); -1 if it is not a Hangul syllable. */
function finalConsonant(word: string): number {
  const c = word
    .replace(/\([^)]*\)$/, '')
    .trim()
    .slice(-1)
    .charCodeAt(0);
  return c >= 0xac00 && c <= 0xd7a3 ? (c - 0xac00) % 28 : -1;
}

/** The word followed by the right particle of the pair. */
export function josa(word: string, pair: JosaPair): string {
  const f = finalConsonant(word);
  // 으로 after a final consonant other than ㄹ; 로 after a vowel or ㄹ.
  if (pair === '으로/로') return word + (f > 0 && f !== 8 ? '으로' : '로');
  const [afterConsonant, afterVowel] = pair.split('/') as [string, string];
  return word + (f > 0 ? afterConsonant : afterVowel);
}
